'use client';

import { useState, useEffect } from 'react';
import { UserProfile, PartialUserProfile } from '@/lib/types/user-profile-types';

const STORAGE_KEY = 'ootday_user_profile';

/**
 * Custom hook for managing user profile state with localStorage persistence
 */
export function useUserProfile() {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Load profile from localStorage on mount
  useEffect(() => {
    loadProfile();
  }, []);

  /**
   * Load user profile from localStorage
   */
  const loadProfile = () => {
    try {
      const storedProfile = localStorage.getItem(STORAGE_KEY);
      if (storedProfile) {
        const parsedProfile = JSON.parse(storedProfile) as UserProfile;
        setProfile(parsedProfile);
      }
    } catch (error) {
      console.error('Error loading user profile:', error);
    } finally {
      setIsLoading(false);
    }
  };

  /**
   * Save user profile to localStorage
   */
  const saveProfile = (profileData: UserProfile) => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profileData));
      setProfile(profileData);
    } catch (error) {
      console.error('Error saving user profile:', error);
    }
  };

  /**
   * Update partial profile data (merge with existing)
   */
  const updateProfile = (updates: PartialUserProfile) => {
    const updatedProfile: UserProfile = {
      userName: updates.userName ?? profile?.userName ?? '',
      gender: updates.gender ?? profile?.gender ?? 'women', // v2.4: Fix - use updates.gender instead of hardcoded value
      ageRange: updates.ageRange ?? profile?.ageRange ?? '<20',
      stylePreferences: updates.stylePreferences ?? profile?.stylePreferences ?? [],
      userPhoto: updates.userPhoto ?? profile?.userPhoto,
      fittingModelUrl: updates.fittingModelUrl ?? profile?.fittingModelUrl,
      onboardingCompleted: updates.onboardingCompleted ?? profile?.onboardingCompleted ?? false,
      createdAt: profile?.createdAt ?? new Date().toISOString(),
    };
    saveProfile(updatedProfile);
  };

  /**
   * Mark onboarding as complete
   */
  const completeOnboarding = () => {
    if (profile) {
      const completedProfile: UserProfile = {
        ...profile,
        onboardingCompleted: true,
      };
      saveProfile(completedProfile);
    }
  };

  /**
   * Clear profile and reset onboarding (for testing)
   */
  const clearProfile = () => {
    try {
      localStorage.removeItem(STORAGE_KEY);
      setProfile(null);
    } catch (error) {
      console.error('Error clearing user profile:', error);
    }
  };

  return {
    profile,
    isLoading,
    loadProfile,
    saveProfile,
    updateProfile,
    completeOnboarding,
    clearProfile,
  };
}

/**
 * Pinterest 2026 Fashion Trends
 *
 * Defines trending aesthetics, color palettes, layering patterns,
 * and styling rules based on Pinterest 2026 fashion trend analysis
 */

// ============================================================================
// Type Definitions
// ============================================================================

/**
 * Aesthetic categories from Pinterest 2026 trends
 */
export type AestheticCategory =
  | 'clean-girl'
  | 'scandinavian-minimal'
  | 'street-style'
  | 'casual-chic'
  | 'y2k-revival'
  | 'corporate-chic'
  | 'quiet-luxury'
  | 'minimalist-office'
  | 'dark-academia'

/**
 * Trending color palette categories
 */
export type ColorPalette =
  | 'neutral-earth-tones'
  | 'monochromatic-beige'
  | 'monochromatic-brown'
  | 'monochromatic-blue'
  | 'monochromatic-black'
  | 'work-olive-black'
  | 'work-brown-cream'
  | 'all-black-texture'

/**
 * Layering pattern types
 */
export type LayeringPattern =
  | 'oversized-sweater-over-tee'
  | 'cardigan-over-fitted-top'
  | 'knit-vest-over-button-up'
  | 'sweater-over-collared-shirt'
  | 'blazer-over-knit'
  | 'cardigan-over-dress'

/**
 * Bottom styling trends
 */
export type BottomStyle =
  | 'baggy-jeans'
  | 'wide-leg-jeans'
  | 'high-waisted-fit'
  | 'cuffed-denim'
  | 'wide-leg-trousers'
  | 'high-waisted-trousers'

/**
 * Footwear trends
 */
export type FootwearTrend =
  | 'platform-sneakers'
  | 'adidas-gazelle-style'
  | 'timberland-boots'
  | 'ugg-style-boots'
  | 'chunky-sneakers'

/**
 * Accessory trends
 */
export type AccessoryTrend =
  | 'black-structured-bag'
  | 'gold-layered-jewelry'
  | 'wide-belt'
  | 'structured-leather-tote'

// ============================================================================
// Color Palette Definitions
// ============================================================================

/**
 * Trending color palettes from Pinterest 2026
 */
export const COLOR_PALETTES: Record<ColorPalette, string[]> = {
  'neutral-earth-tones': ['grey', 'gray', 'beige', 'brown', 'olive', 'taupe', 'cream', 'tan', 'khaki', 'sand'],
  'monochromatic-beige': ['beige', 'cream', 'tan', 'taupe', 'sand', 'ivory', 'ecru'],
  'monochromatic-brown': ['brown', 'chocolate', 'camel', 'coffee', 'mocha', 'cocoa', 'chestnut'],
  'monochromatic-blue': ['blue', 'navy', 'indigo', 'denim', 'cobalt', 'azure', 'steel'],
  'monochromatic-black': ['black', 'charcoal', 'ebony', 'jet', 'onyx'],
  'work-olive-black': ['olive', 'black', 'charcoal', 'forest', 'hunter'],
  'work-brown-cream': ['brown', 'cream', 'beige', 'camel', 'ivory', 'tan'],
  'all-black-texture': ['black', 'charcoal', 'ebony'],
}

/**
 * Get color palette keywords
 */
export function getColorPaletteKeywords(palette: ColorPalette): string[] {
  return COLOR_PALETTES[palette] || []
}

/**
 * Get all neutral earth tone colors
 */
export function getNeutralEarthTones(): string[] {
  return COLOR_PALETTES['neutral-earth-tones']
}

// ============================================================================
// Aesthetic Definitions
// ============================================================================

