/**
 * Get aesthetic definition by name
 */
export function getAestheticDefinition(aesthetic: AestheticCategory): AestheticDefinition | undefined {
  return AESTHETIC_DEFINITIONS[aesthetic]
}

/**
 * Get aesthetics for occasion
