}

/**
 * Get keywords for footwear trend
 */
export function getFootwearKeywords(trend: FootwearTrend): string[] {
  return FOOTWEAR_KEYWORDS[trend] || []
}

/**
 * Get trending footwear for occasion
 */
export function getTrendingFootwear(occasion: 'casual' | 'work'): FootwearTrend[] {
  if (occasion === 'work') {
    return ['platform-sneakers', 'chunky-sneakers']
  }
  return ['platform-sneakers', 'adidas-gazelle-style', 'timberland-boots', 'chunky-sneakers']
}

// ============================================================================
// Accessory Trends
// ============================================================================

export const ACCESSORY_KEYWORDS: Record<AccessoryTrend, string[]> = {
  'black-structured-bag': ['black bag', 'structured bag', 'tote', 'handbag'],
  'gold-layered-jewelry': ['gold', 'jewelry', 'necklace', 'layered', 'chain'],
  'wide-belt': ['wide belt', 'statement belt', 'waist belt'],
  'structured-leather-tote': ['tote', 'leather bag', 'work bag', 'structured'],
}

/**
 * Get keywords for accessory trend
 */
export function getAccessoryKeywords(trend: AccessoryTrend): string[] {
  return ACCESSORY_KEYWORDS[trend] || []
}

/**
 * Get trending accessories for occasion
 */
export function getTrendingAccessories(occasion: 'casual' | 'work'): AccessoryTrend[] {
  if (occasion === 'work') {
    return ['structured-leather-tote', 'gold-layered-jewelry']
  }
  return ['black-structured-bag', 'gold-layered-jewelry', 'wide-belt']
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Detect aesthetic from keywords
 */
export function detectAestheticFromKeywords(keywords: string[]): AestheticCategory | null {
  const lowerKeywords = keywords.map(k => k.toLowerCase())

  // Count matches for each aesthetic
  const matches: Record<AestheticCategory, number> = {} as any

  for (const [aesthetic, definition] of Object.entries(AESTHETIC_DEFINITIONS)) {
    const matchCount = definition.keywords.filter(keyword =>
      lowerKeywords.some(k => k.includes(keyword) || keyword.includes(k))
    ).length

    if (matchCount > 0) {
      matches[aesthetic as AestheticCategory] = matchCount
    }
  }

  // Return aesthetic with most matches
  const entries = Object.entries(matches)
  if (entries.length === 0) return null

  entries.sort((a, b) => b[1] - a[1])
  return entries[0][0] as AestheticCategory
}

/**
 * Get recommended color palettes for aesthetic
 */
export function getRecommendedPalettes(aesthetic: AestheticCategory): ColorPalette[] {
  const definition = AESTHETIC_DEFINITIONS[aesthetic]
  return definition?.colorPalettes || []
}

/**
 * Get recommended layering for aesthetic
 */
export function getRecommendedLayering(aesthetic: AestheticCategory): LayeringPattern[] {
  const definition = AESTHETIC_DEFINITIONS[aesthetic]
  return definition?.layeringPatterns || []
}

/**
 * Check if aesthetic is suitable for occasion
 */
export function isAestheticSuitableForOccasion(aesthetic: AestheticCategory, occasion: string): boolean {
  const definition = AESTHETIC_DEFINITIONS[aesthetic]
  return definition?.occasions.includes(occasion.toLowerCase()) || false
}

/**
 * Outfit Generator
 *
 * Generates fashion outfit recommendations from product catalog
 * Enhanced with Pinterest 2026 trending styles and color palettes
 */

import type { Product, Outfit } from './types'
import type { AestheticCategory, ColorPalette } from './types/enums'
import {
  applyTrendBasedCombination,
  validateOutfitComposition,
  deduplicateOutfitCategories,
} from './styling/outfit-combination-rules'
import { getDominantPalette, calculateColorCoordination } from './styling/color-palette-matcher'
import { detectAestheticFromKeywords } from './styling/pinterest-2026-trends'

/**
 * Product category types for outfit composition
 */
export type ProductCategory = 'tops' | 'bottoms' | 'shoes' | 'dresses' | 'accessories' | 'other'

export interface CategorizedProducts {
  tops: Product[]
  bottoms: Product[]
  shoes: Product[]
  dresses: Product[]
  accessories: Product[]
  other: Product[]
}

/**
 * Outfit style templates
 */
export type OutfitStyle = 'business' | 'casual' | 'formal' | 'weekend' | 'date' | 'workout' | 'any'

/**
 * Categorize a product based on its name and sub-category
 */
export function categorizeProduct(product: Product): ProductCategory {
  const name = product.name.toLowerCase()
  const subCategory = (product as any).subCategory?.toLowerCase() || ''
  const combined = `${name} ${subCategory}`

  // Dresses (standalone outfit items for women)
  if (combined.includes('dress') || combined.includes('กระโปรง')) {
    return 'dresses'
  }

  // Tops (shirts, blouses, t-shirts, tops, blazers, jackets)
  if (
    combined.includes('shirt') ||
    combined.includes('blouse') ||
    combined.includes('t-shirt') ||
    combined.includes('tee') ||
    combined.includes('top') ||
    combined.includes('blazer') ||
    combined.includes('jacket') ||
    combined.includes('coat') ||
    combined.includes('sweater') ||
    combined.includes('hoodie') ||
    combined.includes('เสื้อ')
  ) {
    return 'tops'
  }

  // Bottoms (pants, trousers, jeans, shorts, skirts)
  if (
    combined.includes('pants') ||
    combined.includes('trousers') ||
    combined.includes('jeans') ||
    combined.includes('shorts') ||
    combined.includes('skirt') ||
    combined.includes('กางเกง')
  ) {
    return 'bottoms'
  }

  // Shoes (shoes, boots, sneakers, sandals)
  if (
    combined.includes('shoe') ||
    combined.includes('boot') ||
    combined.includes('sneaker') ||
    combined.includes('sandal') ||
    combined.includes('loafer') ||
    combined.includes('heel') ||
    combined.includes('รองเท้า')
  ) {
    return 'shoes'
  }

  // Accessories (bags, belts, watches, sunglasses, jewelry)
  if (
    combined.includes('bag') ||
    combined.includes('belt') ||
    combined.includes('watch') ||
    combined.includes('sunglass') ||
    combined.includes('jewelry') ||
    combined.includes('necklace') ||
    combined.includes('bracelet') ||
    combined.includes('ring') ||
    combined.includes('earring') ||
    combined.includes('scarf') ||
    combined.includes('hat') ||
    combined.includes('กระเป๋า') ||
    combined.includes('เข็มขัด')
  ) {
    return 'accessories'
  }

  return 'other'
}

/**
 * Categorize a list of products into categories
 */
export function categorizeProducts(products: Product[]): CategorizedProducts {
  const categorized: CategorizedProducts = {
    tops: [],
    bottoms: [],
    shoes: [],
    dresses: [],
    accessories: [],
    other: [],
  }

  for (const product of products) {
    const category = categorizeProduct(product)
    categorized[category].push(product)
  }

  return categorized
}

/**
 * Get random item from array
 */
function randomPick<T>(items: T[]): T | undefined {
  if (items.length === 0) return undefined
  return items[Math.floor(Math.random() * items.length)]
}

/**
 * Get multiple random items from array
 */
function randomPickMultiple<T>(items: T[], count: number): T[] {
  if (items.length === 0) return []
  const shuffled = [...items].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, Math.min(count, items.length))
}

